using System;
using Nethermind.Core.Attributes;
using Nethermind.Core.Crypto;

namespace Nethermind.Core
{
    public class TxReceipt
    {
        private Bloom? _boom;

        public TxReceipt()
        {
        }

        public TxReceipt(TxReceipt other)
        {
            TxType = other.TxType;
            StatusCode = other.StatusCode;
            BlockNumber = other.BlockNumber;
            BlockHash = other.BlockHash;
            TxHash = other.TxHash;
            Index = other.Index;
            GasUsed = other.GasUsed;
            GasUsedTotal = other.GasUsedTotal;
            Sender = other.Sender;
            ContractAddress = other.ContractAddress;
            Recipient = other.Recipient;
            ReturnValue = other.ReturnValue;
            PostTransactionState = other.PostTransactionState;
            Bloom = other.Bloom;
            Logs = other.Logs;
            Error = other.Error;
        }

        /// <summary>
        /// EIP-2718 transaction type
        /// </summary>
        public TxType TxType { get; set; }

        /// <summary>
        ///     EIP-658
        /// </summary>
        public byte StatusCode { get; set; }
        public long BlockNumber { get; set; }
        public Hash256? BlockHash { get; set; }
        public Hash256? TxHash { get; set; }
        public int Index { get; set; }
        public long GasUsed { get; set; }
        public long GasUsedTotal { get; set; }
        public Address? Sender { get; set; }
        public Address? ContractAddress { get; set; }
        public Address? Recipient { get; set; }

        [Todo(Improve.Refactor, "Receipt tracer?")]
        public byte[]? ReturnValue { get; set; }

        /// <summary>

